package com.example.starter.dye.domain;

/**
 * 幂等操作类型，对应染色流转的四类写操作。
 */
public enum OperationType {
    /** 打小样对色 */
    COLOR_MATCH,
    /** 投料执行 */
    FEED,
    /** 缸差判定 */
    JUDGE,
    /** 判定归档 */
    ARCHIVE
}

package com.example.starter.dye.domain;

/**
 * 配方版本状态。
 */
public enum RecipeStatus {
    /** 草稿：可继续修改 */
    DRAFT,
    /** 已发布：冻结，禁止原地修改，改动须生成新版本 */
    PUBLISHED
}

package com.example.starter.dye.domain;

/**
 * 缸次生命周期状态。
 */
public enum RunStatus {
    /** 已排缸，尚未投料 */
    PLANNED,
    /** 投料执行中 */
    RUNNING,
    /** 已出缸，等待缸差判定（回修复检后也回到该状态） */
    DISCHARGED,
    /** 已判定回修，等待复检 */
    REPAIRED,
    /** 已降级处置，等待归档 */
    GRADED_DOWN,
    /** 判定归档（终态） */
    ARCHIVED
}

package com.example.starter.dye.domain;

/**
 * 缸差判定处置结论。
 */
public enum Disposition {
    /** 合格 */
    PASS,
    /** 回修（仅允许一次） */
    REPAIR,
    /** 降级处置（回修后仍超差） */
    GRADED_DOWN
}

