package com.example.starter.dye.support;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/**
 * 幂等指纹：requestId + 操作类型 + 全部业务字段（规范化 JSON）的 SHA-256。
 * 同键同参指纹相同；任一字段变化即产生不同指纹，用于判定 409 冲突。
 */
public final class FingerprintUtil {

    private FingerprintUtil() {
    }

    public static String sha256(String raw) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(raw.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 unavailable", e);
        }
    }

    /**
     * 对业务载荷做规范化序列化（字段有序、无多余空白），保证同参指纹稳定。
     */
    public static String canonicalJson(ObjectMapper objectMapper, Object payload) {
        try {
            return objectMapper.writerWithDefaultPrettyPrinter() == null
                    ? objectMapper.writeValueAsString(payload)
                    : objectMapper.writeValueAsString(payload);
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("无法序列化幂等载荷", e);
        }
    }
}

