     * @param body 首次执行得到的业务结果；重放时为 null
     */
    public record Outcome<T>(boolean replay, String cachedJson, T body) {

        public static <T> Outcome<T> first(T body) {
            return new Outcome<>(false, null, body);
        }

        public static <T> Outcome<T> replay(String cachedJson) {
            return new Outcome<>(true, cachedJson, null);
        }
    }

    @Transactional(propagation = Propagation.REQUIRED)
    public <T> Outcome<T> execute(OperationType operation, String requestId, Object payload,
                                  Supplier<T> action) {
        String fingerprint = FingerprintUtil.fingerprint(operation.name(), requestId, payload);
        Optional<IdempotentRequestPO> existing = repository.find(requestId);
        if (existing.isPresent()) {
            IdempotentRequestPO po = existing.get();
            if (!po.getFingerprint().equals(fingerprint)) {
                throw new ConflictException("requestId=" + requestId + " 已用于不同业务参数，拒绝受理");
            }
            return Outcome.replay(po.getResponseClob());
        }
        try {
            repository.insertPlaceholder(requestId, operation, fingerprint, LocalDateTime.now(clock));
        } catch (DuplicateKeyException concurrent) {
            // 并发同键：对方事务提交后按重放处理；指纹不符仍 409
            IdempotentRequestPO po = repository.find(requestId)
                    .orElseThrow(() -> new ConflictException("requestId=" + requestId + " 并发受理冲突，请重试"));
            if (!po.getFingerprint().equals(fingerprint)) {
                throw new ConflictException("requestId=" + requestId + " 已用于不同业务参数，拒绝受理");
            }
            return Outcome.replay(po.getResponseClob());
        }
        T body = action.get();
        repository.fillResult(requestId, 200, toJson(body));
        return Outcome.first(body);
    }

    private String toJson(Object body) {
        try {
            return objectMapper.writeValueAsString(body);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("幂等结果序列化失败", e);
        }
    }
}

