                return replayOrConflict(committed, fingerprint, requestId);
            }
            // 占位行消失（对方回滚），重试插入
        }
    }
    ServiceResult<T> result = action.get();
    repository.fillResult(requestId, result.statusCode(), toJson(result.body()));
    return Outcome.first(result);
}

